func twoSum(nums []int, target int) []int {
	seen := make(map[int]int)
	for i, x := range nums {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}

// ListNode is supplied by LeetCode: struct { Val int; Next *ListNode }.
func addTwoNumbers(l1 *ListNode, l2 *ListNode) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	carry := 0
	for l1 != nil || l2 != nil || carry != 0 {
		sum := carry
		if l1 != nil {
			sum += l1.Val
			l1 = l1.Next
		}
		if l2 != nil {
			sum += l2.Val
			l2 = l2.Next
		}
		tail.Next = &ListNode{Val: sum % 10}
		tail = tail.Next
		carry = sum / 10
	}
	return dummy.Next
}

func lengthOfLongestSubstring(s string) int {
	last := make(map[byte]int)
	left, best := 0, 0
	for right := 0; right < len(s); right++ {
		if p, ok := last[s[right]]; ok && p >= left {
			left = p + 1
		}
		last[s[right]] = right
		if right-left+1 > best {
			best = right - left + 1
		}
	}
	return best
}

func findMedianSortedArrays(nums1 []int, nums2 []int) float64 {
	if len(nums1) > len(nums2) {
		return findMedianSortedArrays(nums2, nums1)
	}
	m, n := len(nums1), len(nums2)
	lo, hi := 0, m
	for lo <= hi {
		i := (lo + hi) / 2
		j := (m+n+1)/2 - i
		if i < m && j > 0 && nums2[j-1] > nums1[i] {
			lo = i + 1
			continue
		}
		if i > 0 && j < n && nums1[i-1] > nums2[j] {
			hi = i - 1
			continue
		}
		left := 0
		if i == 0 {
			left = nums2[j-1]
		} else if j == 0 || nums1[i-1] > nums2[j-1] {
			left = nums1[i-1]
		} else {
			left = nums2[j-1]
		}
		if (m+n)%2 == 1 {
			return float64(left)
		}
		right := 0
		if i == m {
			right = nums2[j]
		} else if j == n || nums1[i] < nums2[j] {
			right = nums1[i]
		} else {
			right = nums2[j]
		}
		return (float64(left) + float64(right)) / 2
	}
	return 0
}

func longestPalindrome(s string) string {
	if len(s) == 0 {
		return ""
	}
	// Interleave virtual separators: even positions separate original bytes.
	size := 2*len(s) + 1
	radius := make([]int, size)
	center, right := 0, 0
	bestCenter, bestRadius := 0, 0
	equal := func(a, b int) bool {
		if a%2 == 0 {
			return b%2 == 0
		}
		return b%2 == 1 && s[a/2] == s[b/2]
	}
	for i := 0; i < size; i++ {
		if i < right {
			mirror := 2*center - i
			radius[i] = radius[mirror]
			if radius[i] > right-i {
				radius[i] = right - i
			}
		}
		for i-radius[i]-1 >= 0 && i+radius[i]+1 < size && equal(i-radius[i]-1, i+radius[i]+1) {
			radius[i]++
		}
		if i+radius[i] > right {
			center, right = i, i+radius[i]
		}
		if radius[i] > bestRadius {
			bestCenter, bestRadius = i, radius[i]
		}
	}
	start := (bestCenter - bestRadius) / 2
	return s[start : start+bestRadius]
}

import "strings"

func convert(s string, numRows int) string {
	if numRows <= 1 || numRows >= len(s) {
		return s
	}
	rows := make([]strings.Builder, numRows)
	row, step := 0, 1
	for i := 0; i < len(s); i++ {
		rows[row].WriteByte(s[i])
		if row == 0 {
			step = 1
		} else if row == numRows-1 {
			step = -1
		}
		row += step
	}
	var out strings.Builder
	out.Grow(len(s))
	for i := range rows {
		out.WriteString(rows[i].String())
	}
	return out.String()
}

func reverse(x int) int {
	result := 0
	for x != 0 {
		d := x % 10
		x /= 10
		if result > 214748364 || result == 214748364 && d > 7 || result < -214748364 || result == -214748364 && d < -8 {
			return 0
		}
		result = result*10 + d
	}
	return result
}

func myAtoi(s string) int {
	i := 0
	for i < len(s) && s[i] == ' ' {
		i++
	}
	sign := 1
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		if s[i] == '-' {
			sign = -1
		}
		i++
	}
	limit := 2147483647
	if sign < 0 {
		limit++
	}
	value := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		d := int(s[i] - '0')
		if value > (limit-d)/10 {
			return sign * limit
		}
		value = value*10 + d
		i++
	}
	return sign * value
}

func isPalindrome(x int) bool {
	if x < 0 || x != 0 && x%10 == 0 {
		return false
	}
	reversed := 0
	for x > reversed {
		reversed = reversed*10 + x%10
		x /= 10
	}
	return x == reversed || x == reversed/10
}

func isMatch(s string, p string) bool {
	prev := make([]bool, len(p)+1)
	prev[0] = true
	for j := 2; j <= len(p); j++ {
		if p[j-1] == '*' {
			prev[j] = prev[j-2]
		}
	}
	for i := 1; i <= len(s); i++ {
		cur := make([]bool, len(p)+1)
		for j := 1; j <= len(p); j++ {
			if p[j-1] == '*' {
				cur[j] = cur[j-2] || (p[j-2] == '.' || p[j-2] == s[i-1]) && prev[j]
			} else {
				cur[j] = (p[j-1] == '.' || p[j-1] == s[i-1]) && prev[j-1]
			}
		}
		prev = cur
	}
	return prev[len(p)]
}

func maxArea(height []int) int {
	l, r, best := 0, len(height)-1, 0
	for l < r {
		h := height[l]
		if height[r] < h {
			h = height[r]
		}
		area := (r - l) * h
		if area > best {
			best = area
		}
		if height[l] < height[r] {
			l++
		} else {
			r--
		}
	}
	return best
}

import "strings"

func intToRoman(num int) string {
	values := []int{1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1}
	symbols := []string{"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"}
	var out strings.Builder
	for i, v := range values {
		for num >= v {
			out.WriteString(symbols[i])
			num -= v
		}
	}
	return out.String()
}

func romanToInt(s string) int {
	value := map[byte]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	total := 0
	for i := 0; i < len(s); i++ {
		v := value[s[i]]
		if i+1 < len(s) && v < value[s[i+1]] {
			total -= v
		} else {
			total += v
		}
	}
	return total
}

func longestCommonPrefix(strs []string) string {
	if len(strs) == 0 {
		return ""
	}
	for i := 0; i < len(strs[0]); i++ {
		for _, s := range strs[1:] {
			if i >= len(s) || s[i] != strs[0][i] {
				return strs[0][:i]
			}
		}
	}
	return strs[0]
}

import "sort"

func threeSum(nums []int) [][]int {
	sort.Ints(nums)
	out := make([][]int, 0)
	for i := 0; i+2 < len(nums); i++ {
		if i > 0 && nums[i] == nums[i-1] {
			continue
		}
		if nums[i] > 0 {
			break
		}
		l, r := i+1, len(nums)-1
		for l < r {
			sum := nums[i] + nums[l] + nums[r]
			if sum < 0 {
				l++
			} else if sum > 0 {
				r--
			} else {
				out = append(out, []int{nums[i], nums[l], nums[r]})
				l++
				r--
				for l < r && nums[l] == nums[l-1] {
					l++
				}
				for l < r && nums[r] == nums[r+1] {
					r--
				}
			}
		}
	}
	return out
}

import "sort"

func threeSumClosest(nums []int, target int) int {
	sort.Ints(nums)
	best := nums[0] + nums[1] + nums[2]
	abs := func(x int) int {
		if x < 0 {
			return -x
		}
		return x
	}
	for i := 0; i+2 < len(nums); i++ {
		l, r := i+1, len(nums)-1
		for l < r {
			sum := nums[i] + nums[l] + nums[r]
			if abs(sum-target) < abs(best-target) {
				best = sum
			}
			if sum == target {
				return sum
			}
			if sum < target {
				l++
			} else {
				r--
			}
		}
	}
	return best
}

func letterCombinations(digits string) []string {
	out := make([]string, 0)
	if len(digits) == 0 {
		return out
	}
	keys := []string{"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"}
	buf := make([]byte, len(digits))
	var visit func(int)
	visit = func(i int) {
		if i == len(digits) {
			out = append(out, string(buf))
			return
		}
		letters := keys[digits[i]-'0']
		for j := 0; j < len(letters); j++ {
			buf[i] = letters[j]
			visit(i + 1)
		}
	}
	visit(0)
	return out
}

import "sort"

func fourSum(nums []int, target int) [][]int {
	sort.Ints(nums)
	out := make([][]int, 0)
	n := len(nums)
	for i := 0; i+3 < n; i++ {
		if i > 0 && nums[i] == nums[i-1] {
			continue
		}
		for j := i + 1; j+2 < n; j++ {
			if j > i+1 && nums[j] == nums[j-1] {
				continue
			}
			l, r := j+1, n-1
			for l < r {
				sum := int64(nums[i]) + int64(nums[j]) + int64(nums[l]) + int64(nums[r])
				if sum < int64(target) {
					l++
				} else if sum > int64(target) {
					r--
				} else {
					out = append(out, []int{nums[i], nums[j], nums[l], nums[r]})
					l++
					r--
					for l < r && nums[l] == nums[l-1] {
						l++
					}
					for l < r && nums[r] == nums[r+1] {
						r--
					}
				}
			}
		}
	}
	return out
}

// ListNode is supplied by LeetCode.
func removeNthFromEnd(head *ListNode, n int) *ListNode {
	dummy := &ListNode{Next: head}
	fast, slow := dummy, dummy
	for i := 0; i < n; i++ {
		fast = fast.Next
	}
	for fast.Next != nil {
		fast = fast.Next
		slow = slow.Next
	}
	slow.Next = slow.Next.Next
	return dummy.Next
}

func isValid(s string) bool {
	stack := make([]byte, 0, len(s))
	pairs := map[byte]byte{')': '(', ']': '[', '}': '{'}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '(' || c == '[' || c == '{' {
			stack = append(stack, c)
		} else {
			if len(stack) == 0 || stack[len(stack)-1] != pairs[c] {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

// ListNode is supplied by LeetCode.
func mergeTwoLists(list1 *ListNode, list2 *ListNode) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	for list1 != nil && list2 != nil {
		if list1.Val <= list2.Val {
			tail.Next = list1
			list1 = list1.Next
		} else {
			tail.Next = list2
			list2 = list2.Next
		}
		tail = tail.Next
	}
	if list1 != nil {
		tail.Next = list1
	} else {
		tail.Next = list2
	}
	return dummy.Next
}

func generateParenthesis(n int) []string {
	out := make([]string, 0)
	buf := make([]byte, 2*n)
	var visit func(int, int)
	visit = func(open, close int) {
		if close == n {
			out = append(out, string(buf))
			return
		}
		if open < n {
			buf[open+close] = '('
			visit(open+1, close)
		}
		if close < open {
			buf[open+close] = ')'
			visit(open, close+1)
		}
	}
	visit(0, 0)
	return out
}

import "container/heap"

// ListNode is supplied by LeetCode.
type nodeHeap []*ListNode

func (h nodeHeap) Len() int           { return len(h) }
func (h nodeHeap) Less(i, j int) bool { return h[i].Val < h[j].Val }
func (h nodeHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *nodeHeap) Push(x any)        { *h = append(*h, x.(*ListNode)) }
func (h *nodeHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	old[n-1] = nil
	*h = old[:n-1]
	return x
}
func mergeKLists(lists []*ListNode) *ListNode {
	h := nodeHeap{}
	for _, node := range lists {
		if node != nil {
			h = append(h, node)
		}
	}
	heap.Init(&h)
	dummy := &ListNode{}
	tail := dummy
	for len(h) > 0 {
		node := heap.Pop(&h).(*ListNode)
		if node.Next != nil {
			heap.Push(&h, node.Next)
		}
		tail.Next = node
		tail = node
	}
	return dummy.Next
}

// ListNode is supplied by LeetCode.
func swapPairs(head *ListNode) *ListNode {
	dummy := &ListNode{Next: head}
	prev := dummy
	for prev.Next != nil && prev.Next.Next != nil {
		a := prev.Next
		b := a.Next
		a.Next = b.Next
		b.Next = a
		prev.Next = b
		prev = a
	}
	return dummy.Next
}

// ListNode is supplied by LeetCode.
func reverseKGroup(head *ListNode, k int) *ListNode {
	dummy := &ListNode{Next: head}
	before := dummy
	for {
		last := before
		for i := 0; i < k && last != nil; i++ {
			last = last.Next
		}
		if last == nil {
			break
		}
		after := last.Next
		prev, cur := after, before.Next
		for cur != after {
			next := cur.Next
			cur.Next = prev
			prev = cur
			cur = next
		}
		oldFirst := before.Next
		before.Next = last
		before = oldFirst
	}
	return dummy.Next
}

func removeDuplicates(nums []int) int {
	write := 0
	for _, x := range nums {
		if write == 0 || x != nums[write-1] {
			nums[write] = x
			write++
		}
	}
	return write
}

func removeElement(nums []int, val int) int {
	write := 0
	for _, x := range nums {
		if x != val {
			nums[write] = x
			write++
		}
	}
	return write
}

func strStr(haystack string, needle string) int {
	if len(needle) == 0 {
		return 0
	}
	pi := make([]int, len(needle))
	for i, j := 1, 0; i < len(needle); i++ {
		for j > 0 && needle[i] != needle[j] {
			j = pi[j-1]
		}
		if needle[i] == needle[j] {
			j++
		}
		pi[i] = j
	}
	for i, j := 0, 0; i < len(haystack); i++ {
		for j > 0 && haystack[i] != needle[j] {
			j = pi[j-1]
		}
		if haystack[i] == needle[j] {
			j++
		}
		if j == len(needle) {
			return i - j + 1
		}
	}
	return -1
}

func divide(dividend int, divisor int) int {
	if dividend == -2147483648 && divisor == -1 {
		return 2147483647
	}
	a, b := int64(dividend), int64(divisor)
	negative := (a < 0) != (b < 0)
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	q := int64(0)
	for bit := 31; bit >= 0; bit-- {
		if a>>bit >= b {
			a -= b << bit
			q |= int64(1) << bit
		}
	}
	if negative {
		q = -q
	}
	return int(q)
}

func findSubstring(s string, words []string) []int {
	out := make([]int, 0)
	if len(words) == 0 || len(words[0]) == 0 {
		return out
	}
	w := len(words[0])
	need := map[string]int{}
	for _, word := range words {
		need[word]++
	}
	for offset := 0; offset < w; offset++ {
		left, count := offset, 0
		have := map[string]int{}
		for right := offset; right+w <= len(s); right += w {
			word := s[right : right+w]
			if need[word] == 0 {
				clear(have)
				count = 0
				left = right + w
				continue
			}
			have[word]++
			count++
			for have[word] > need[word] {
				old := s[left : left+w]
				have[old]--
				count--
				left += w
			}
			if count == len(words) {
				out = append(out, left)
				old := s[left : left+w]
				have[old]--
				count--
				left += w
			}
		}
	}
	return out
}

func nextPermutation(nums []int) {
	i := len(nums) - 2
	for i >= 0 && nums[i] >= nums[i+1] {
		i--
	}
	if i >= 0 {
		j := len(nums) - 1
		for nums[j] <= nums[i] {
			j--
		}
		nums[i], nums[j] = nums[j], nums[i]
	}
	for l, r := i+1, len(nums)-1; l < r; l, r = l+1, r-1 {
		nums[l], nums[r] = nums[r], nums[l]
	}
}

func longestValidParentheses(s string) int {
	stack := []int{-1}
	best := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '(' {
			stack = append(stack, i)
		} else {
			stack = stack[:len(stack)-1]
			if len(stack) == 0 {
				stack = append(stack, i)
			} else if i-stack[len(stack)-1] > best {
				best = i - stack[len(stack)-1]
			}
		}
	}
	return best
}

func search(nums []int, target int) int {
	lo, hi := 0, len(nums)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2
		if nums[mid] == target {
			return mid
		}
		if nums[lo] <= nums[mid] {
			if nums[lo] <= target && target < nums[mid] {
				hi = mid - 1
			} else {
				lo = mid + 1
			}
		} else {
			if nums[mid] < target && target <= nums[hi] {
				lo = mid + 1
			} else {
				hi = mid - 1
			}
		}
	}
	return -1
}

func searchRange(nums []int, target int) []int {
	bound := func(strict bool) int {
		lo, hi := 0, len(nums)
		for lo < hi {
			mid := lo + (hi-lo)/2
			if nums[mid] < target || strict && nums[mid] == target {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		return lo
	}
	first := bound(false)
	if first == len(nums) || nums[first] != target {
		return []int{-1, -1}
	}
	return []int{first, bound(true) - 1}
}

func searchInsert(nums []int, target int) int {
	lo, hi := 0, len(nums)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

func isValidSudoku(board [][]byte) bool {
	var rows, cols, boxes [9]int
	for r := 0; r < 9; r++ {
		for c := 0; c < 9; c++ {
			if board[r][c] == '.' {
				continue
			}
			bit := 1 << uint(board[r][c]-'1')
			b := r/3*3 + c/3
			if rows[r]&bit != 0 || cols[c]&bit != 0 || boxes[b]&bit != 0 {
				return false
			}
			rows[r] |= bit
			cols[c] |= bit
			boxes[b] |= bit
		}
	}
	return true
}

import "math/bits"

func solveSudoku(board [][]byte) {
	var rows, cols, boxes [9]int
	cells := [][2]int{}
	for r := 0; r < 9; r++ {
		for c := 0; c < 9; c++ {
			if board[r][c] == '.' {
				cells = append(cells, [2]int{r, c})
			} else {
				bit := 1 << uint(board[r][c]-'1')
				rows[r] |= bit
				cols[c] |= bit
				boxes[r/3*3+c/3] |= bit
			}
		}
	}
	var solve func(int) bool
	solve = func(pos int) bool {
		if pos == len(cells) {
			return true
		}
		best, minCount := pos, 10
		for i := pos; i < len(cells); i++ {
			r, c := cells[i][0], cells[i][1]
			count := bits.OnesCount(uint(511 & ^(rows[r] | cols[c] | boxes[r/3*3+c/3])))
			if count < minCount {
				best, minCount = i, count
			}
		}
		cells[pos], cells[best] = cells[best], cells[pos]
		r, c := cells[pos][0], cells[pos][1]
		b := r/3*3 + c/3
		available := 511 & ^(rows[r] | cols[c] | boxes[b])
		for available != 0 {
			bit := available & -available
			available -= bit
			rows[r] |= bit
			cols[c] |= bit
			boxes[b] |= bit
			board[r][c] = byte('1' + bits.TrailingZeros(uint(bit)))
			if solve(pos + 1) {
				return true
			}
			rows[r] &^= bit
			cols[c] &^= bit
			boxes[b] &^= bit
		}
		board[r][c] = '.'
		cells[pos], cells[best] = cells[best], cells[pos]
		return false
	}
	solve(0)
}

