	for i := len(num1) - 1; i >= 0; i-- {
		for j := len(num2) - 1; j >= 0; j-- {
			sum := int(num1[i]-'0')*int(num2[j]-'0') + digits[i+j+1]
			digits[i+j+1] = sum % 10
			digits[i+j] += sum / 10
		}
	}
	start := 0
	for start < len(digits)-1 && digits[start] == 0 {
		start++
	}
	out := make([]byte, len(digits)-start)
	for i := range out {
