	}
	n := len(matrix[0])
	lo, hi := 0, len(matrix)*n
	for lo < hi {
		mid := lo + (hi-lo)/2
		x := matrix[mid/n][mid%n]
		if x < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo < len(matrix)*n && matrix[lo/n][lo%n] == target
}

func sortColors(nums []int) {
	low, mid, high := 0, 0, len(nums)-1
	for mid <= high {
		switch nums[mid] {
		case 0:
			nums[low], nums[mid] = nums[mid], nums[low]
			low++
			mid++
		case 1:
			mid++
		case 2:
