func minWindow(s string, t string) string {
	if len(t) == 0 {
		return ""
	}
	var need [256]int
	for i := 0; i < len(t); i++ {
		need[t[i]]++
	}
	missing := len(t)
	left, bestStart, bestLen := 0, 0, len(s)+1
	for right := 0; right < len(s); right++ {
		c := s[right]
		if need[c] > 0 {
			missing--
		}
		need[c]--
		for missing == 0 {
			if right-left+1 < bestLen {
				bestStart, bestLen = left, right-left+1
			}
			c = s[left]
			need[c]++
			if need[c] > 0 {
				missing++
			}
			left++
		}
	}
	if bestLen > len(s) {
		return ""
	}
	return s[bestStart : bestStart+bestLen]
}

func combine(n int, k int) [][]int {
	out := make([][]int, 0)
	path := make([]int, 0, k)
	var visit func(int)
	visit = func(start int) {
		if len(path) == k {
			out = append(out, append([]int{}, path...))
			return
		}
		last := n - (k - len(path)) + 1
		for x := start; x <= last; x++ {
			path = append(path, x)
			visit(x + 1)
			path = path[:len(path)-1]
		}
	}
	visit(1)
	return out
}

